// Term-led explainer registry (A5): for every card in the catalog, each reported statistic gets ONE
// entry: bold term -> one-sentence meaning -> interpretation of THIS run's value with the number woven
// in (owner's R² example is normative). `key` matches the registry column key / reported stat name
// (machine-checked for full coverage by explainers.consistency.test.ts). `interpret` reads from
// `ResultValues`, a flat lookup populated per-card by `CardContent.values` (wired per builder).
//
// U8-T4 completed coverage for the remaining 42 cards (plus extending the 6 U8-T1 representative
// cards' key sets where their own tables surface more columns than those first 6 entries covered).
// Multi-row/open-cardinality tables (e.g. an ANOVA source table, a coefficient table with several
// predictors, CB-SEM's per-item/per-construct measurement tables) can't bind ONE value per key, so
// those entries either (a) pick the card's own headline/primary row (mirroring what the card's own
// apaTemplate already treats as "the" result), or (b) report a real aggregate (a min-max range, a
// count) computed from the same numbers already rendered into the table - documented inline per card,
// same "aggregate" convention as multiple-linear-regression's vifMax.

export type ResultValues = Record<string, number | string | null | undefined>

export interface Explainer {
  key: string
  term: string
  meaning: string
  interpret: (v: ResultValues) => string
}

